def count_components(n, edges):
    parent = list(range(n))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    for a, b in edges:
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb; n -= 1
    return n

class Trie:
    def __init__(self): self.root = {}
    def insert(self, word):
        node = self.root
        for ch in word: node = node.setdefault(ch, {})
        node["$"] = True
    def search(self, word):
        node = self.root
        for ch in word:
            if ch not in node: return False
            node = node[ch]
        return "$" in node

def lookup(root, ip):
    best, node = None, root
    for i in range(31, -1, -1):
        if "hop" in node:
            best = node["hop"]
        node = node.get((ip >> i) & 1)
        if node is None:
            return best
    return node.get("hop", best)

class WordDictionary:
    def __init__(self):
        self.root = {}
    def add_word(self, word):
        node = self.root
        for ch in word:
            node = node.setdefault(ch, {})
        node["$"] = True
    def search(self, word):
        def go(i, node):
            if i == len(word):
                return "$" in node
            ch = word[i]
            if ch == ".":
                return any(go(i + 1, child) for k, child in node.items() if k != "$")
            return ch in node and go(i + 1, node[ch])
        return go(0, self.root)
